INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q7845067', 'Trois Glorieuses', 'The Trois Glorieuses (lit. ''Three Glorious Days'') was an uprising in Congo-Brazzaville which occurred from August 13 to 15, 1963. The uprising ended the rule of the first Congolese President, Fulbert Youlou, as the opposition trade union movement and Congolese Youth Union struck an alliance with the army.', 1963, NULL, NULL, 1963, 8, 15, 'year', '1963', 30, 'https://en.wikipedia.org/wiki/Trois_Glorieuses_(1963)'),
  ('Q25043463', '1968 Republic of the Congo coup d''état', 'On September 4, 1968, following several days of violent clashes, Alphonse Massamba-Débat''s government was overthrown by the military who forced Massamba-Débat to resign. Alfred Raoul then became the acting head of state until January 1969 when Marien Ngouabi, the chairman of the same party that had brought Massamba-Débat to power, assumed control.', 1968, 9, 4, NULL, NULL, NULL, 'day', '4 September 1968', 34, 'https://en.wikipedia.org/wiki/1968_Republic_of_the_Congo_coup_d''%C3%A9tat'),
  ('Q6720472', 'M 22', 'M 22 (short for Mouvement 22 de fevrier, ''February 22 Movement'') was a political movement in Congo-Brazzaville. It was active in 1972 and 73 before its guerrilla base was compromised and most of its cadre arrested including its leader Ange Diawara.', 1972, 2, 22, 1976, NULL, NULL, 'day', '22 February 1972 – 1976', 34, 'https://en.wikipedia.org/wiki/M_22'),
  ('Q20982378', 'First Republic of the Congo Civil War', 'The First Republic of the Congo Civil War, also known as the First Brazzaville-Congolese Civil War, was a conflict in the Republic of the Congo which lasted from 2 November 1993 to 30 January 1994 and was between rival militias led by former politician Bernard Kolelas, former Prime Minister Pascal Lissouba, and former President Denis Sassou-Nguesso. It was one of four instances of militia fighting within the country, setting the stage for the next three conflicts in 1997, 1998–99, and 2002.', 1994, 12, NULL, 1994, 1, 30, 'month', 'December 1994 – 30 January 1994', 37, 'https://en.wikipedia.org/wiki/Republic_of_the_Congo_Civil_War_(1993%E2%80%931994)'),
  ('Q1021172', 'Republic of the Congo civil war', 'The Second Republic of the Congo Civil War, also known as the Second Brazzaville-Congolese Civil War, was the second of two ethnopolitical civil conflicts in the Republic of the Congo which lasted from 5 June 1997 to 29 December 1999. The war served as the continuation of the civil war of 1993–1994 and involved militias representing three political candidates.', 1999, 12, 29, 1999, NULL, NULL, 'day', '1999', 52, 'https://en.wikipedia.org/wiki/Republic_of_the_Congo_Civil_War_(1997%E2%80%931999)'),
  ('Q1188883', 'Brazzaville arms dump blasts', 'On 4 March 2012, a series of blasts occurred at an army arms dump in Brazzaville, the capital of the Republic of the Congo. At least 300 people were killed by the explosions.', 2012, 3, 4, NULL, NULL, NULL, 'day', '4 March 2012', 43, 'https://en.wikipedia.org/wiki/Brazzaville_arms_dump_blasts'),
